import React, { useState } from 'react';
import '../App.css';
import { useNavigate } from 'react-router-dom';
import { toast, ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const uploadTypes = [
  'Cognizant Holiday',
  'Associate Holiday',
  'Baseline',
  'BFD',
  'Upside'
];

const UploadPage = () => {
  const navigate = useNavigate();
  const [files, setFiles] = useState({});

  const handleFileChange = (type, file) => {
    setFiles((prev) => ({ ...prev, [type]: file }));
  };

  const handleUpload = async (type) => {
    const file = files[type];
    if (!file) {
      toast.warning(`⚠️ Please select a file for ${type}`);
      return;
    }

    const formData = new FormData();
    const keyMap = {
      'Baseline': 'baseline',
      'BFD': 'bfd',
      'Cognizant Holiday': 'cognizantHoliday',
      'Associate Holiday': 'associateHoliday'
    };

    const backendKey = keyMap[type];
    if (!backendKey) {
      toast.error(`${type} upload not supported yet.`);
      return;
    }

    formData.append(backendKey, file);

    try {
      const response = await fetch('http://localhost:8081/upload', {
        method: 'POST',
        body: formData
      });

      const result = await response.text();
      toast.success(result);
    } catch (error) {
      console.error('Upload failed:', error);
      toast.error('❌ Upload failed. Please try again.');
    }
  };

  const handleCancel = (type) => {
    setFiles((prev) => ({ ...prev, [type]: null }));
  };

  return (
    <div className="upload-page">
      <ToastContainer />
      <h2>Upload Excel Files</h2>
      <div className="upload-cards">
        {uploadTypes.map((type) => (
          <div key={type} className="upload-card">
            <h3>{type}</h3>
            <input
              type="file"
              accept=".xlsx, .xls"
              onChange={(e) => handleFileChange(type, e.target.files[0])}
            />
            {files[type] && <p>Selected: {files[type].name}</p>}
            <div className="card-buttons">
              <button onClick={() => handleUpload(type)}>
                <i className="fas fa-upload"></i> Upload
              </button>
              <button onClick={() => handleCancel(type)}>
                <i className="fas fa-times-circle"></i> Cancel
              </button>
            </div>
          </div>
        ))}
      </div>
      <div className="navigation-buttons">
        <button onClick={() => navigate('/')}>
          <i className="fas fa-arrow-left"></i> Back
        </button>
        <button onClick={() => navigate('/dashboard')}>
          <i className="fas fa-chart-line"></i> View Dashboard
        </button>
      </div>
    </div>
  );
};

export default UploadPage;
